public class Main {
    static int countPositive(int[] values) {
        int count = 0;
        for (int value : values) {
            if (value > 0) {
                count = count + 1;
            }
        }
        return count;
    }
    public static void main(String[] args) {
        int[] values = {-1, 0, 2, 3};
        System.out.println(countPositive(values));
    }
}

